package com.craftdistrict.block;

import net.minecraft.world.level.block.Block;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

/** Generated by tools/generate_refrigerated_displays.py. Sealed cases share shapes. */
final class RefrigeratedDisplayShapes {
    static final VoxelShape[][] SHAPES = {
            rotations(Shapes.or(
                    Block.box(0.75, 0, 0.875, 16, 7.75, 15.5),
                    Block.box(0.75, 7.75, 1.125, 16, 16, 15.5)).optimize()),
            rotations(Shapes.or(
                    Block.box(0, 0, 0.875, 15.25, 7.75, 15.5),
                    Block.box(0, 7.75, 1.125, 15.25, 16, 15.5)).optimize()),
            rotations(Shapes.or(
                    Block.box(0.75, 0, 1.125, 16, 15.5, 15.5),
                    Block.box(12.5, 0.75, 15.5, 13.125, 5.875, 16)).optimize()),
            rotations(Shapes.or(
                    Block.box(0, 0, 1.125, 15.25, 15.5, 15.5),
                    Block.box(2.75, 0.75, 15.5, 3.375, 5.875, 16)).optimize())
    };

    private RefrigeratedDisplayShapes() {
    }

    private static VoxelShape[] rotations(VoxelShape north) {
        VoxelShape[] shapes = new VoxelShape[4];
        shapes[0] = north;
        for (int turn = 1; turn < 4; turn++) {
            VoxelShape rotated = Shapes.empty();
            for (AABB box : shapes[turn - 1].toAabbs()) {
                rotated = Shapes.or(rotated, Shapes.box(1 - box.maxZ, box.minY, box.minX,
                        1 - box.minZ, box.maxY, box.maxX));
            }
            shapes[turn] = rotated.optimize();
        }
        return shapes;
    }
}
